import{_ as p,a0 as o,w as r,s as d,ao as l,I as a,x as e,a1 as i,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"五条强化 SSH 安全的建议 | LCTT x X-CMD","titleTemplate":false,"description":"五条强化 SSH 安全的建议 | LCTT (201608) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"五条强化 SSH 安全的建议 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"五条强化 SSH 安全的建议 | LCTT (201608) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201608/20160620 5 SSH Hardening Tips","title":"五条强化 SSH 安全的建议","tag":"201608","desc":""},"relativePath":"201608/20160620 5 SSH Hardening Tips.md","filePath":"[post].md"}'),h={name:"201608/20160620 5 SSH Hardening Tips.md"};function u(g,s,k,b,m,c){const n=o("Link");return r(),d("div",null,[s[25]||(s[25]=l('<h1 id="五条强化-ssh-安全的建议" tabindex="-1">五条强化 SSH 安全的建议 <a class="header-anchor" href="#五条强化-ssh-安全的建议" aria-label="Permalink to “五条强化 SSH 安全的建议”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/binary-1188510_1920_0.jpg?itok=ocPCL_9G" alt=""></p><p><em>采用这些简单的建议，使你的 OpenSSH 会话更加安全。</em></p><p>当你查看你的 SSH 服务日志，可能你会发现充斥着一些不怀好意的尝试性登录。这里有 5 条常规建议（和一些个别特殊策略）可以让你的 OpenSSH 会话更加安全。</p><h3 id="_1-强化密码登录" tabindex="-1">1. 强化密码登录 <a class="header-anchor" href="#_1-强化密码登录" aria-label="Permalink to “1. 强化密码登录”">​</a></h3><p>密码登录很方便，因为你可以从任何地方的任何机器上登录。但是它们在暴力攻击面前也是脆弱的。尝试以下策略来强化你的密码登录。</p>',6)),a("ul",null,[s[6]||(s[6]=a("li",null,[e("使用一个密码生成工具，例如 pwgen。pwgen 有几个选项，最有用的就是密码长度的选项（例如，"),a("code",null,"pwgen 12"),e(" 产生一个12位字符的密码）")],-1)),a("li",null,[s[1]||(s[1]=e("不要重复使用密码。忽略所有那些不要写下你的密码的建议，然后将你的所有登录信息都记在一个本子上。如果你不相信我的建议，那总可以相信安全权威 ",-1)),i(n,{href:"https://www.schneier.com/blog/archives/2005/06/write_down_your.html"},{default:t(()=>[...s[0]||(s[0]=[e("Bruce Schneier",-1)])]),_:1}),s[2]||(s[2]=e(" 吧。如果你足够细心，没有人能够发现你的笔记本，那么这样能够不受到网络上的那些攻击。",-1))]),s[7]||(s[7]=a("li",null,[e("你可以为你的登录记事本增加一些额外的保护措施，例如用字符替换或者增加新的字符来掩盖笔记本上的登录密码。使用一个简单而且好记的规则，比如说给你的密码增加两个额外的随机字符，或者使用单个简单的字符替换，例如 "),a("code",null,"#"),e(" 替换成 "),a("code",null,"*"),e("。")],-1)),s[8]||(s[8]=a("li",null,"为你的 SSH 服务开启一个非默认的监听端口。是的，这是很老套的建议，但是它确实很有效。检查你的登录；很有可能 22 端口是被普遍攻击的端口，其他端口则很少被攻击。",-1)),a("li",null,[s[4]||(s[4]=e("使用 ",-1)),i(n,{href:"http://www.fail2ban.org/wiki/index.php/Main_Page"},{default:t(()=>[...s[3]||(s[3]=[e("Fail2ban",-1)])]),_:1}),s[5]||(s[5]=e(" 来动态保护你的服务器，是服务器免于被暴力攻击。",-1))]),s[9]||(s[9]=a("li",null,"使用不常用的用户名。绝不能让 root 可以远程登录，并避免用户名为“admin”。",-1))]),s[26]||(s[26]=l(`<h3 id="_2-解决-too-many-authentication-failures-报错" tabindex="-1">2. 解决 <code>Too Many Authentication Failures</code> 报错 <a class="header-anchor" href="#_2-解决-too-many-authentication-failures-报错" aria-label="Permalink to “2. 解决 Too Many Authentication Failures 报错”">​</a></h3><p>当我的 ssh 登录失败，并显示“Too many authentication failures for carla”的报错信息时，我很难过。我知道我应该不介意，但是这报错确实很碍眼。而且，正如我聪慧的奶奶曾经说过，伤痛之感并不能解决问题。解决办法就是在你的（客户端的） <code>~/.ssh/config</code> 文件设置强制密码登录。如果这个文件不存在，首先创个 <code>~/.ssh/</code> 目录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir ~/.ssh</span></span>
<span class="line"><span>$ chmod 700 ~/.ssh</span></span></code></pre></div><p>然后在一个文本编辑器创建 <code>~/.ssh/confg</code> 文件，输入以下行，使用你自己的远程域名替换 HostName。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HostName remote.site.com</span></span>
<span class="line"><span>PubkeyAuthentication=no</span></span></code></pre></div><p>（LCTT 译注：这种错误发生在你使用一台 Linux 机器使用 ssh 登录另外一台服务器时，你的 .ssh 目录中存储了过多的私钥文件，而 ssh 客户端在你没有指定 -i 选项时，会默认逐一尝试使用这些私钥来登录远程服务器后才会提示密码登录，如果这些私钥并不能匹配远程主机，显然会触发这样的报错，甚至拒绝连接。因此本条是通过禁用本地私钥的方式来强制使用密码登录——显然这并不可取，如果你确实要避免用私钥登录，那你应该用 <code>-o PubkeyAuthentication=no</code> 选项登录。显然这条和下两条是互相矛盾的，所以请无视本条即可。）</p><h3 id="_3-使用公钥认证" tabindex="-1">3. 使用公钥认证 <a class="header-anchor" href="#_3-使用公钥认证" aria-label="Permalink to “3. 使用公钥认证”">​</a></h3><p>公钥认证比密码登录安全多了，因为它不受暴力密码攻击的影响，但是并不方便因为它依赖于 RSA 密钥对。首先，你要创建一个公钥/私钥对。下一步，私钥放于你的客户端电脑，并且复制公钥到你想登录的远程服务器。你只能从拥有私钥的电脑登录才能登录到远程服务器。你的私钥就和你的家门钥匙一样敏感；任何人获取到了私钥就可以获取你的账号。你可以给你的私钥加上密码来增加一些强化保护规则。</p><p>使用 RSA 密钥对管理多个用户是一种好的方法。当一个用户离开了，只要从服务器删了他的公钥就能取消他的登录。</p><p>以下例子创建一个新的 3072 位长度的密钥对，它比默认的 2048 位更安全，而且为它起一个独一无二的名字，这样你就可以知道它属于哪个服务器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh-keygen -t rsa -b 3072 -f id_mailserver</span></span></code></pre></div><p>以下创建两个新的密钥, <code>id_mailserver</code> 和 <code>id_mailserver.pub</code>，<code>id_mailserver</code> 是你的私钥--不要传播它！现在用 <code>ssh-copy-id</code> 命令安全地复制你的公钥到你的远程服务器。你必须确保在远程服务器上有可用的 SSH 登录方式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh-copy-id -i  id_rsa.pub user@remoteserver</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/usr/bin/ssh-copy-id: INFO: attempting to log in with the new key(s), to filter out any that are already installed</span></span>
<span class="line"><span>user@remoteserver&#39;s password:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Number of key(s) added: 1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Now try logging into the machine, with:   &quot;ssh &#39;user@remoteserver&#39;&quot;</span></span>
<span class="line"><span>and check to make sure that only the key(s) you wanted were added.</span></span></code></pre></div><p><code>ssh-copy-id</code> 会确保你不会无意间复制了你的私钥。从上述输出中复制登录命令，记得带上其中的单引号，以测试你的新的密钥登录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh &#39;user@remoteserver&#39;</span></span></code></pre></div><p>它将用你的新密钥登录，如果你为你的私钥设置了密码，它会提示你输入。</p><h3 id="_4-取消密码登录" tabindex="-1">4. 取消密码登录 <a class="header-anchor" href="#_4-取消密码登录" aria-label="Permalink to “4. 取消密码登录”">​</a></h3><p>一旦你已经测试并且验证了你的公钥可以登录，就可以取消密码登录，这样你的远程服务器就不会被暴力密码攻击。如下设置<strong>你的远程服务器</strong>的 <code>/etc/sshd_config</code> 文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PasswordAuthentication no</span></span></code></pre></div><p>然后重启服务器上的 SSH 守护进程。</p><h3 id="_5-设置别名-这很快捷而且很有-b-格" tabindex="-1">5. 设置别名 -- 这很快捷而且很有 B 格 <a class="header-anchor" href="#_5-设置别名-这很快捷而且很有-b-格" aria-label="Permalink to “5. 设置别名 -- 这很快捷而且很有 B 格”">​</a></h3><p>你可以为你的远程登录设置常用的别名，来替代登录时输入的命令，例如 <code>ssh -u username -p 2222 remote.site.with.long-name</code>。你可以使用 <code>ssh remote1</code>。你的客户端机器上的 <code>~/.ssh/config</code> 文件可以参照如下设置</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Host remote1</span></span>
<span class="line"><span>HostName remote.site.with.long-name</span></span>
<span class="line"><span>Port 2222</span></span>
<span class="line"><span>User username</span></span>
<span class="line"><span>PubkeyAuthentication no</span></span></code></pre></div><p>如果你正在使用公钥登录，可以参照这个：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Host remote1</span></span>
<span class="line"><span>HostName remote.site.with.long-name</span></span>
<span class="line"><span>Port 2222</span></span>
<span class="line"><span>User username</span></span>
<span class="line"><span>IdentityFile  ~/.ssh/id_remoteserver</span></span></code></pre></div>`,25)),a("p",null,[i(n,{href:"http://www.openssh.com/"},{default:t(()=>[...s[10]||(s[10]=[e("OpenSSH 文档",-1)])]),_:1}),s[11]||(s[11]=e(" 很长而且详细，但是当你掌握了基础的 SSH 使用规则之后，你会发现它非常的有用，而且包含很多可以通过 OpenSSH 来实现的炫酷效果。",-1))]),s[27]||(s[27]=a("hr",null,null,-1)),a("p",null,[s[13]||(s[13]=e("via: ",-1)),i(n,{href:"https://www.linux.com/learn/5-ssh-hardening-tips"},{default:t(()=>[...s[12]||(s[12]=[e("https://www.linux.com/learn/5-ssh-hardening-tips",-1)])]),_:1})]),a("p",null,[s[17]||(s[17]=e("作者：",-1)),i(n,{href:"https://www.linux.com/users/cschroder"},{default:t(()=>[...s[14]||(s[14]=[e("CARLA SCHRODER",-1)])]),_:1}),s[18]||(s[18]=e(" 译者：",-1)),i(n,{href:"https://github.com/maywanting"},{default:t(()=>[...s[15]||(s[15]=[e("maywanting",-1)])]),_:1}),s[19]||(s[19]=e(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[16]||(s[16]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[22]||(s[22]=e("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[20]||(s[20]=[e("LCTT",-1)])]),_:1}),s[23]||(s[23]=e(" 原创翻译，",-1)),i(n,{href:"https://linux.cn/"},{default:t(()=>[...s[21]||(s[21]=[e("Linux中国",-1)])]),_:1}),s[24]||(s[24]=e(" 荣誉推出",-1))])])}const w=p(h,[["render",u]]);export{S as __pageData,w as default};
